import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    static class DSU {
        long[] parent;

        DSU(long n) {
            parent = new long[(int) n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        long findSet(long a) {
            if (a == parent[(int) a]) {
                return a;
            }
            long base = findSet(parent[(int) a]);
            parent[(int) a] = base;
            return base;
        }

        void unionSet(long a, long b) {
            a = findSet(a);
            b = findSet(b);
            if (a != b) {
                if (new Random().nextInt(2) == 0) {
                    long temp = a;
                    a = b;
                    b = temp;
                }
                parent[(int) b] = a;
            }
        }
    }

    static long countCycles(long p, long k) {
        DSU dsu = new DSU(p);
        for (long i = 1; i < p; i++) {
            long ki = (k * i) % p;
            dsu.unionSet(i, ki);
        }

        boolean[] found = new boolean[(int) p];
        long count = 0;
        for (long i = 1; i < p; i++) {
            long base = dsu.findSet(i);
            if (!found[(int) base]) {
                found[(int) base] = true;
                count++;
            }
        }
        return count;
    }

    static long countSolutions(long p, long k) {
        long cycles;
        if (k == 0) {
            cycles = p - 1;
        } else if (k == 1) {
            cycles = p;
        } else {
            cycles = countCycles(p, k);
        }

        long count = 1;
        for (long i = 0; i < cycles; i++) {
            count = (count * p) % MOD;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        long count = countSolutions(p, k);
        System.out.println(count);
        int end = sc.nextInt(); // Read to match original code's input
        sc.close();
    }
}
